One of the most powerful frameworks to extract information out of this type of asymptotic series is Borel analysis, where one starts with the \textit{Borel transform}; a linear map acting on formal power series

\begin{align}
{\cal B} \colon {\mathbb C} [[x]] &\rightarrow {\mathbb C} [[s]] \\
x^{\alpha+1} &\mapsto {\cal B} \left[ x^{\alpha+1} \right](s) = \frac{s^{\alpha}}{\Gamma(\alpha+1)}.
\label{boreltrans}
\end{align}

\begin{align}
{\cal B} \colon {\mathbb C} [[x]] &\rightarrow {\mathbb C} [[s]] \\
x^{\alpha+1} &\mapsto {\cal B} \left[ x^{\alpha+1} \right](s) = \frac{s^{\alpha}}{\Gamma(\alpha+1)}.
\label{boreltrans}
\end{align}

Once this is done, and chosen a direction $\theta$ in the complex $s$-plane along which ${\cal B} [\Phi^{(0)}] (s)$ has no singularities, the \textit{Borel resummation} (or inverse Borel transform)

\begin{equation}
\label{borelresum}
{\cal S}_\theta \Phi^{(0)} (x) = \int_0^{{\mathrm{e}}^{{\mathrm{i}}\theta}\infty} {\mathrm{d}} s\, {\cal B}[\Phi^{(0)}](s)\, {\mathrm{e}}^{-\frac{s}{x}}
\end{equation}

The lateral Borel resummations lead to \textit{distinct} sectorial resummations of our original asymptotic series, but they are nonetheless \textit{connected} via the so-called \textit{Stokes automorphism} $\underline{\mathfrak{S}}_\theta$,

\begin{equation}\label{stokesauto}
{\cal S}_{\theta^+} = {\cal S}_{\theta^-} \circ \underline{\mathfrak{S}}_\theta.
\end{equation}

For example, a transseries \textit{ansatz} for our resurgent function, depending on a single parameter $\sigma$, could be

\begin{equation}
\label{Phitransseries}
\Phi (x,\sigma) = \sum_{n=0}^{+\infty} \sigma^n\, \Phi^{(n)} (x),
\end{equation}

Consider the ``quartic partition function'', described by

\begin{equation}
\label{quarticintegral}
Z (\hbar) = \frac{1}{2\pi} \int_{\Gamma} {\mathrm{d}} z\, {\mathrm{e}}^{- \frac{1}{\hbar} V(z)},
\end{equation}

\noindent
where $V(z)$ is the quartic potential

\begin{equation}
\label{quarticpotential}
V(z) = \frac{1}{2} z^2 - \frac{\lambda}{24} z^4,
\end{equation}

With a simple change of variables the partition function \eqref{quarticintegral} may be written as

\begin{equation}
\label{quarticintegralX}
Z (x) = \frac{\sqrt{\hbar}}{2\pi} \int_{\Gamma} {\mathrm{d}} z\, \exp \left( - \frac{1}{2} z^2 + \frac{x}{24} z^4 \right),
\end{equation}

Next, chosen a reference saddle $z^*$, one deforms the contour of integration into the infinite, oriented path of steepest descent through $z^*$, defined as

\begin{equation}
\label{steepestdescentcontour-def}
{\mathbb{I}}{\mathrm{m}} \left( V(z) - V(z^*) \right) = 0,
\end{equation}

\begin{eqnarray}
