\label{coeff-quartic-inst}
\Phi_{1} (x) &\simeq& \sum_{n=0}^{+\infty} Z^{(1)}_n\, x^n, \qquad Z^{(1)}_n = (-1)^n \left( \frac{2}{3} \right)^n \frac{(4n)!}{2^{6n}\, (2n)!\, n!}\, Z^{(1)}_0.
