\Phi_4 + 3 S_{-1}\, {\mathrm{e}}^{\frac{A}{x}} \Phi_3 + \left( 2 S_{-2} + \frac{6}{2!} S_{-1}^2 \right) {\mathrm{e}}^{\frac{2A}{x}} \Phi_2 + \left( S_{-3} + \frac{5}{2!} S_{-1} S_{-2} + \frac{6}{3!} S_{-1}^3 \right) {\mathrm{e}}^{\frac{3A}{x}} \Phi_1 \nonumber \\
&=&
\Phi_4 - \mathsf{S}_{4\to3}\, {\mathrm{e}}^{\frac{A}{x}}\, \Phi_3 - \mathsf{S}_{4\to2}\, {\mathrm{e}}^{\frac{2A}{x}}\, \Phi_2 - \mathsf{S}_{4\to1}\, {\mathrm{e}}^{\frac{3A}{x}}\, \Phi_1.
\label{stokes-pi-one-param-expanded}
\end{eqnarray}

In this case, the \textit{two}-parameter transseries that fully describes the quartic free energy should be

\begin{equation}
\label{two-param-quartic}
F (x, \sigma_1, \sigma_2) = \sum_{n=0}^{+\infty} \sum_{m=0}^{+\infty} \sigma_1^n\, \sigma_2^m\, {\mathrm{e}}^{-\frac{n A}{x}}\, \Phi_{(n,m)} (x).
\end{equation}

Indeed, looking back at \eqref{two-param-quartic}, it turns out that one can ``hide'' the second parameter into the definition of new ``hatted'' coefficients as

\begin{equation}
\label{two-into-one-param-quartic}
F (x, \sigma_1, \sigma_2) = \sum_{n=0}^{+\infty} \sigma_1^n\, {\mathrm{e}}^{-\frac{n A}{x}}\, \widehat{\Phi}_{n} (x),
\end{equation}

\noindent
where

\begin{equation}
\label{two-into-one-param-sectors-quartic}
\widehat{\Phi}_{n}(x) \simeq \sum_{k=0}^{+\infty} \widehat{F}_{k}^{(n)}\, x^{k}, \qquad\widehat{F}_{k}^{(n)} := \sum_{m=0}^{+\infty} \sigma_2^m\, F_{k}^{(n,m)}.
\end{equation}

\noindent
The main reason why one can restrict our two-parameter transseries into the form of a one-parameter transseries with an added single sector is the same reason why we were able to ``hide'' the second parameter in \eqref{two-into-one-param-sectors-quartic}: one can check that the sectors associated to $\Phi_{(n,m)}$ with $m$ non-zero will \textit{not} be asymptotic; with all asymptotic behaviour being restricted to the $\Phi_{(n,0)}$. Still, our solution to the ODE does tell us that one\footnote{In principle one could include several sectors $\Phi_{(0,m)}$, but they would all be constant and indistinguishable, which in the end does amount to a single contribution.} extra sector needs to be included (albeit non-asymptotic), associated to the action $A=0$---and \eqref{01nonasymptsector} is it. Notice that these asymptotic statements have a rather natural explanation\footnote{By this we mean an explanation going beyond the fact that resurgence \textit{dictates} them (our emphasis in these lectures), \textit{i.e.}, that our \textit{ansatz} is indeed strongly validated by the associated large-order relations arising from resurgence---which we shall get to discuss in detail a bit later on, in subsection~\ref{sec:large-order-F}.} by looking at the quartic free-energy second-order ODE \eqref{quarticNLODE}. Indeed, this equation has \textit{no} dependence on $F(x)$ itself, but only on \textit{derivatives} of $F(x)$. It can then be trivially integrated into a \textit{first}-order ODE by the redefinition $\mathfrak{F} (x) \equiv F' (x)$, where the new sector which we have just uncovered can then be identified with the integration constant associated to this redefinition. Another natural explanation will soon be obtained when we directly compare linear and nonlinear problems (\textit{i.e.}, the quartic partition function and free energy) in the next subsection. To make all these statements a bit more clear, let us finally rewrite the transseries solution as

\begin{equation}
\label{one-point-five-transseries}
F (x, \sigma_1, \sigma_2) = \sum_{n=0}^{+\infty} \sigma_1^n\, {\mathrm{e}}^{-\frac{n A}{x}}\, \Phi_{(n,0)} (x) + \sigma_2\, F_0^{(0,1)}.
\end{equation}

One expects only mild corrections to \eqref{Borel-transf-expanded-one-param} and performing similar calculations as in, \textit{e.g.}, \cite{asv11}, it is simple to obtain

\begin{equation}
\label{Borel-transf-expanded-one-point-five}
{\cal B} [\Phi_{(n,0)}] (s+kA) = \left( \mathsf{S}_{n\to n+k} \times {\cal B} [\Phi_{(n+k,0)}] (s) + \delta_{n+k}\, \widetilde{\mathsf{S}}_{n\to n+k} \times {\cal B} [\Phi_{(0,1)}] (s) \right) \frac{\log s}{2\pi{\mathrm{i}}}, \qquad k \neq 0,
\end{equation}

\noindent
where now $\widetilde{\mathsf{S}}_{n\to0} \neq 0$.

\begin{equation}
\label{Borel-transf-expanded-one-point-five}
{\cal B} [\Phi_{(n,0)}] (s+kA) = \left( \mathsf{S}_{n\to n+k} \times {\cal B} [\Phi_{(n+k,0)}] (s) + \delta_{n+k}\, \widetilde{\mathsf{S}}_{n\to n+k} \times {\cal B} [\Phi_{(0,1)}] (s) \right) \frac{\log s}{2\pi{\mathrm{i}}}, \qquad k \neq 0,
\end{equation}

\begin{eqnarray}
\label{stokes-pi-1inst-quartic}
{\mathrm{Disc}}_{\pi} \Phi_{(1,0)}(x) &=& - \widetilde{S}_{-1}\, {\mathrm{e}}^{\frac{A}{x}}\, \Phi_{(0,1)} = \widetilde{\mathsf{S}}_{1\to0}\, {\mathrm{e}}^{\frac{A}{x}}\, \Phi_{(0,1)}, \\
\label{stokes-pi-2inst-quartic}
{\mathrm{Disc}}_{\pi} \Phi_{(2,0)}(x) &=& - S_{-1}\, {\mathrm{e}}^{\frac{A}{x}}\, \Phi_{(1,0)}(x) - \left( \widetilde{S}_{-2} + \frac{1}{2!} S_{-1} \widetilde{S}_{-1} \right) {\mathrm{e}}^{\frac{2A}{x}}\, \Phi_{(0,1)} \\
&=& \mathsf{S}_{2\to1}\, {\mathrm{e}}^{\frac{A}{x}}\, \Phi_{(1,0)}(x) + \widetilde{\mathsf{S}}_{2\to0}\, {\mathrm{e}}^{\frac{2A}{x}}\, \Phi_{(0,1)}, \nonumber \\
\label{stokes-pi-3inst-quartic}
{\mathrm{Disc}}_{\pi} \Phi_{(3,0)}(x) &=& - 2S_{-1}\, {\mathrm{e}}^{\frac{A}{x}}\, \Phi_{(2,0)}(x) - \left( \frac{2}{2!} S_{-1}^2 + S_{-2} \right) {\mathrm{e}}^{\frac{2A}{x}}\, \Phi_{(1,0)}(x) - \\
&&
- \left( \frac{2}{3!} S_{-1}^2 \widetilde{S}_{-1} + \frac{1}{2!} S_{-2} \widetilde{S}_{-1} + \frac{2}{2!} S_{-1} \widetilde{S}_{-2} + \widetilde{S}_{-3} \right) {\mathrm{e}}^{\frac{3A}{x}}\, \Phi_{(0,1)} \nonumber \\
&=& \mathsf{S}_{3\to2}\, {\mathrm{e}}^{\frac{A}{x}}\, \Phi_{(2,0)}(x) + \mathsf{S}_{3\to1}\, {\mathrm{e}}^{\frac{2A}{x}}\, \Phi_{(1,0)}(x) + \widetilde{\mathsf{S}}_{3\to0}\, {\mathrm{e}}^{\frac{3A}{x}}\, \Phi_{(0,1)}.
\nonumber
\end{eqnarray}

\begin{equation}
\label{F0fromZ0}
F^{(0)} = \log Z^{(0)} \simeq \frac{1}{2} \log \frac{\hbar}{2\pi} + \frac{1}{8}\, x + \frac{1}{12}\, x^2 + \frac{11}{96}\, x^3 + \frac{17}{72} x^4 + \frac{619}{960}\, x^5 + \cdots,
\end{equation}

First, the partition function transseries \eqref{quartictransseries} is slightly rewritten as

\begin{equation}
{\cal Z} (x, \sigma_{0}, \sigma_{1}) = \sigma_{0}\, \Phi_0 (x) + \sigma_{1}\, {\mathrm{e}}^{-\frac{3}{2x}}\, \Phi_1 (x) = \sigma_{0}\, \Phi_0 (x) \left( 1 + \zeta\, {\mathrm{e}}^{-\frac{3}{2x}}\, \frac{\Phi_1 (x)}{\Phi_0 (x)} \right),
\end{equation}

\noindent
where we have introduced $\zeta \equiv \frac{\sigma_1}{\sigma_0}$.

\begin{eqnarray}
\underline{\mathfrak{S}}_{0} {\cal Z} (x, \sigma_{0}, \sigma_{1}) &:=& \exp \left( {\mathrm{e}}^{-\frac{A}{x}} \Delta_{+A} \right) {\cal Z} (x, \sigma_{0}, \sigma_{1}) = {\cal Z} (x, \sigma_{0}, \sigma_{1} + S_{1}^{Z} \sigma_{0} ) = \nonumber \\
&\equiv& \exp \left\{ S_{1}^{Z}\, \sigma_{0} \frac{\partial}{\partial\sigma_{1}} \right\} {\cal Z} (x, \sigma_{0}, \sigma_{1}), 
\label{stokes-zero-sigmas}\\
\underline{\mathfrak{S}}_{\pi} {\cal Z} (x, \sigma_{0}, \sigma_{1}) &:=& \exp \left( {\mathrm{e}}^{+\frac{A}{x}} \Delta_{-A} \right) {\cal Z} (x, \sigma_{0}, \sigma_{1}) = {\cal Z} (x, \sigma_{0} + S_{-1}^{Z} \sigma_{1}, \sigma_{1} ) = \nonumber \\
&\equiv& \exp \left\{ S_{-1}^{Z}\, \sigma_{1} \frac{\partial}{\partial\sigma_{0}} \right\} {\cal Z} (x, \sigma_{0}, \sigma_{1}).
\label{stokes-pi-sigmas}
\end{eqnarray}

It is then straightforward to write the analogues of \eqref{stokes-zero-sigmas} and \eqref{stokes-pi-sigmas} for the free energy as

\begin{eqnarray}
\label{eq:Stokes-aut-zero-v1}
\underline{\mathfrak{S}}_{0} F (x, \tau_1, \tau_2) &=& F \left(x, \tau_1+S_{1}^{Z}, \tau_{2}\right), \\
\label{eq:Stokes-aut-pi-v1}
\underline{\mathfrak{S}}_{\pi} F (x, \tau_1, \tau_2) &=& F \left(x, \frac{\tau_1}{1 + S_{-1}^{Z} \tau_{1}}, \tau_{2} + \log \left( 1 + S_{-1}^{Z} \tau_{1} \right) \right).
\end{eqnarray}

\begin{eqnarray}
\label{eq:Stokes-aut-zero-v1}
\underline{\mathfrak{S}}_{0} F (x, \tau_1, \tau_2) &=& F \left(x, \tau_1+S_{1}^{Z}, \tau_{2}\right), \\
\label{eq:Stokes-aut-pi-v1}
\underline{\mathfrak{S}}_{\pi} F (x, \tau_1, \tau_2) &=& F \left(x, \frac{\tau_1}{1 + S_{-1}^{Z} \tau_{1}}, \tau_{2} + \log \left( 1 + S_{-1}^{Z} \tau_{1} \right) \right).
\end{eqnarray}

\begin{eqnarray}
{\mathrm{e}}^{-\frac{A}{x}} \Delta_{+A} F &=& \sum_{n=0}^{+\infty} \tau_1^n\, {\mathrm{e}}^{- \left( n+1 \right) \frac{A}{x}}\, \Delta_{+A} \Phi_{(n,0)} = S_{1}^{F}\, \sum_{n=0}^{+\infty} \tau_{1}^{n} \left( n+1 \right) {\mathrm{e}}^{- \left( n+1 \right) \frac{A}{x}}\, \Phi_{(n+1,0)} = \nonumber \\
&=& S_{1}^{F} \frac{\partial}{\partial\tau_{1}} F,
\end{eqnarray}

\noindent
now leading to the action of the Stokes automorphism \eqref{one-param-stokes-pi} as

\begin{equation}
\label{eq:Stokes-aut-pi-v2}
\underline{\mathfrak{S}}_{\pi} F (x, \tau_{1}, \tau_{2}) = \exp \left\{ \sum_{k=1}^{+\infty} \left( S_{-k}^{F}\, \tau_1^{k+1} \frac{\partial}{\partial\tau_1} + \widetilde{S}_{-k}^F\, \tau_1^k \frac{\partial}{\partial\tau_2} \right) \right\} F (x, \tau_{1}, \tau_{2}).
\end{equation}

\begin{eqnarray}
\label{Stokes-freeen-pi-from-partfunc}
F \left(x, \frac{\tau_1}{1 + S_{-1}^{Z} \tau_{1}}, \tau_{2} + \log \left( 1 + S_{-1}^{Z} \tau_{1} \right) \right) &=& \\
&&
\hspace{-100pt}
= \tau_2 + \log \left( 1 + S_{-1}^{Z} \tau_{1} \right) + \sum_{n=0}^{+\infty} \left( \frac{\tau_1}{1 + S_{-1}^{Z} \tau_{1}} \right)^n {\mathrm{e}}^{-\frac{n A}{x}}\, F^{(n)} (x). \nonumber
\end{eqnarray}

\begin{eqnarray}
\label{Stokes-comp-one}
\ell = 1: & -S_{-1}^{Z} & = S_{-1}^{F}, \\
\label{Stokes-comp-two}
\ell = 2: & \left( -S_{-1}^{Z} \right)^{2} & = S_{-2}^{F} + \frac{1}{2!} \left( 1+1 \right) \left( S_{-1}^{F} \right)^{2}, \\
\label{Stokes-comp-three}
\ell = 3: & \left( -S_{-1}^{Z} \right)^{3} & = S_{-3}^{F} + \frac{1}{2!} \left( 2+3 \right) S_{-1}^{F} S_{-2}^{F} + \frac{1}{3!} \left( 2 \times 3 \right) \left( S_{-1}^{F} \right)^{3}.
\end{eqnarray}

These results tell us that a large number of Stokes constants for the free energy actually vanish. This will be numerically checked via large-order analysis in the next subsection. For the moment let us just note that this implies that some of the resurgence relations allowed for in \eqref{Delta-ka-one-point-five} are in fact trivial, \textit{e.g.},

\begin{equation}
\Delta_{nA}\Phi_{(m,0)}(x) \equiv 0, \qquad n\ne-1,1.
\end{equation}

This is immediately made explicit once one uses the respective relation between transseries parameters \eqref{transseries-sigma-vs-tau}, to find

\begin{eqnarray}
\sigma_{0} \frac{\partial}{\partial\sigma_{1}} &=& \frac{\partial}{\partial\tau_1}, \\
\sigma_{1} \frac{\partial}{\partial\sigma_{0}} &=& - \tau_{1}^2 \frac{\partial}{\partial\tau_{1}} + \tau_{1} \frac{\partial}{\partial\tau_{2}}.
\end{eqnarray}

There is yet another way to see how all this is not a big surprise, but rather a straightforward consequence\footnote{In all rigour, this is more of a consistency check that $\Delta_\omega$ is a derivation, as we have not addressed such proof.} of the fact that $\Delta_\omega$ is a derivation. If $\Delta_\omega$ is a derivation and at some specific point $\omega$ one has $\Delta_\omega Z = 0$, then it must be the case that at this same point one finds $\Delta_\omega F = 0$, as $F = \log Z$. But then all the possibilities encoded in \eqref{Delta-kAF:generic} must immediately simplify, as $\Delta_{-kA} Z = 0$ for $k\ge2$. In fact, this condition sets $\Delta_{-kA} F = 0$ for $k\ge2$, which further yields $S_{-k}^{F} = 0$ and $\widetilde{S}_{-k}^{F} = 0$ for $k\ge2$ (indeed, as was later found in \eqref{eq:Stokes-consts-relation-4} and \eqref{eq:Stokes-consts-relation-5}). In other words, the resurgence relations for the partition function, \eqref{Delta+A} and \eqref{Delta-A}, alongside the fact that $\Delta_\omega$ is a derivation, are enough to tell us that the only non-zero result in \eqref{Delta-kAF:generic} must be

\begin{equation}
{\mathrm{e}}^{\frac{A}{x}} \Delta_{-A} F = \left( S_{-1}^{F}\, \tau_1^{2} \frac{\partial}{\partial\tau_1} + \widetilde{S}_{-1}^F\, \tau_1 \frac{\partial}{\partial\tau_2} \right) F.
\end{equation}

\begin{eqnarray}
