&& + 2^{-k}\, S_1^2 \left( F_0^{(2,0)} + \frac{2A}{k-1}\, F_1^{(2,0)} + \frac{(2A)^2}{(k-1)(k-2)}\, F_2^{(2,0)} + \cdots \right) + \mathcal{O}(3^{-k}). \nonumber
\end{eqnarray}

