Start with the one-dimensional time-independent Schr\"odinger equation,

\begin{equation}
\left( - \frac{\hbar^2}{2m}\, \frac{{\mathrm{d}}^2}{{\mathrm{d}} q^2} + V(q) \right) \psi(q) = E\, \psi (q),
\end{equation}

WKB analysis now follows via its familiar \textit{ansatz} for the wavefunction solution,

\begin{equation}
\label{WKB-app}
\psi(q) = \exp \left( \frac{{\mathrm{i}}}{\hbar} \int_{q_0}^q {\mathrm{d}} z\, \mathsf{V} (z,\hbar) \right),
\end{equation}

\noindent
where $\mathsf{V} (q,\hbar)$ satisfies the Riccati equation $\mathsf{V}^2 - {\mathrm{i}}\hbar\, \mathsf{V}' = p^2$ via \eqref{gen-schrodinger-app} and should be thought of as a power series in $\hbar$,

\begin{equation}
\label{V-exp-app}
\mathsf{V} (q,\hbar) = \mathsf{V}_0 (q) + \hbar\, \mathsf{V}_1 (q) + \hbar^2\, \mathsf{V}_2 (q) + \cdots.
\end{equation}

\noindent
In other words, a (perturbative) WKB solution to the above one-dimensional time-independent Schr\"odinger equation is determined by the recursion:

\begin{eqnarray}
\label{pmp-app}
\mathsf{V}_0 &=& \pm p, \\
\mathsf{V}_n &=& \frac{1}{2 \mathsf{V}_0} \left( {\mathrm{i}} \frac{{\mathrm{d}}}{{\mathrm{d}} q} \mathsf{V}_{n-1} - \sum_{k=1}^{n-1} \mathsf{V}_{k}\, \mathsf{V}_{n-k} \right).
\end{eqnarray}

